import json,sys
d=json.load(sys.stdin)
for f in d['data']['__schema']['queryType']['fields']:
    if f['name'] in ('issues','searchIssues'):
        print(f['name'])
        for a in f['args']:
            print('  ', a['name'], a['type']['kind'], a['type'].get('name'))
"

